// MiCartera R31k0 — Yahoo fundamentals + scheduled news
const ALLOWED_ORIGINS=new Set(["https://rauh1702.github.io","http://localhost:8000","http://127.0.0.1:8000"]);
const UA="Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/131.0.0.0 Safari/537.36";
function cors(o){const h={"Access-Control-Allow-Methods":"GET, POST, OPTIONS","Access-Control-Allow-Headers":"Content-Type","Access-Control-Max-Age":"86400","Vary":"Origin"};if(o&&ALLOWED_ORIGINS.has(o))h["Access-Control-Allow-Origin"]=o;return h;}
function out(d,s,o){const h=new Headers(cors(o));h.set("Content-Type","application/json; charset=utf-8");h.set("Cache-Control","no-store");return new Response(JSON.stringify(d),{status:s,headers:h});}
function cookies(h){const a=typeof h.getSetCookie==="function"?h.getSetCookie():[h.get("Set-Cookie")||""];return a.map(x=>x.split(";")[0].trim()).filter(x=>/^[^=]+=/.test(x)).join("; ");}
async function yahooSession(){const seed=await fetch("https://fc.yahoo.com/",{headers:{"User-Agent":UA},redirect:"manual"});let ck=cookies(seed.headers);if(!ck)throw Error("Yahoo no entregó cookie de sesión");const r=await fetch("https://query1.finance.yahoo.com/v1/test/getcrumb",{headers:{"User-Agent":UA,"Cookie":ck},redirect:"manual"});const crumb=(await r.text()).trim();if(!r.ok||!crumb||crumb.length>200||/unauthorized|<html/i.test(crumb))throw Error("Yahoo no emitió crumb válido");ck=[ck,cookies(r.headers)].filter(Boolean).join("; ");return{ck,crumb};}
async function getFundamentals(symbol){const{ck,crumb}=await yahooSession(),u=new URL("https://query1.finance.yahoo.com/v10/finance/quoteSummary/"+encodeURIComponent(symbol));u.searchParams.set("modules","price,summaryDetail,defaultKeyStatistics,financialData,assetProfile");u.searchParams.set("formatted","true");u.searchParams.set("crumb",crumb);const r=await fetch(u,{headers:{"User-Agent":UA,"Cookie":ck,"Referer":"https://finance.yahoo.com/"} });const body=await r.text();if(!r.ok)throw Error("Yahoo quoteSummary HTTP "+r.status);return JSON.parse(body);}
function impact(t){t=String(t||"").toLowerCase();const p=["beats estimates","record revenue","raises guidance","contract win","awarded contract","approval","partnership","supera previsiones","récord de ingresos","eleva previsiones","contrato","aprobación","alianza"];const n=["misses estimates","cuts guidance","downgrade","dilution","share offering","investigation","lawsuit","delay","loss widens","incumple previsiones","recorta previsiones","ampliación de capital","investigación","demanda","retraso","pérdidas"];const a=p.filter(x=>t.includes(x)).length,b=n.filter(x=>t.includes(x)).length;return a>b?"positive":b>a?"negative":"neutral";}
async function newsFor(symbol){const u=new URL("https://query1.finance.yahoo.com/v1/finance/search");u.searchParams.set("q",symbol);u.searchParams.set("quotesCount","0");u.searchParams.set("newsCount","12");u.searchParams.set("listsCount","0");const r=await fetch(u,{headers:{"User-Agent":UA}});if(!r.ok)throw Error("Yahoo news HTTP "+r.status);const d=await r.json();return(d.news||[]).map(n=>{const title=n.title||"Noticia sin titular",summary=String(n.summary||n.description||title).slice(0,650),url=n.link||n.canonicalUrl?.url||"",ts=Number(n.providerPublishTime)||0;return{id:n.uuid||url,title,summary,url,publisher:n.publisher||"Yahoo Finance",publishedAt:ts?new Date(ts*1000).toISOString():null,symbols:[symbol],impact:impact(title+" "+summary)};}).filter(x=>x.url);}
async function symbols(env){const x=await env.NEWS_KV.get("news:symbols");return x?JSON.parse(x):[];}
async function refresh(env,list){if(!env.NEWS_KV)throw Error("Configura el binding NEWS_KV");const merged=new Map();for(const s of [...new Set(list)].slice(0,40)){try{for(const n of await newsFor(s)){const old=merged.get(n.url);if(old)old.symbols.push(s);else merged.set(n.url,n);}}catch(e){/* continúa con los demás tickers */}}const items=[...merged.values()].map(n=>({...n,symbols:[...new Set(n.symbols)]})).sort((a,b)=>(b.publishedAt||"").localeCompare(a.publishedAt||"")).slice(0,250);const data={items,updatedAt:new Date().toISOString()};await env.NEWS_KV.put("news:latest",JSON.stringify(data));return data;}
export default {async fetch(req,env){const u=new URL(req.url),o=req.headers.get("Origin")||"";if(req.method==="OPTIONS")return new Response(null,{status:o&&!ALLOWED_ORIGINS.has(o)?403:204,headers:cors(o)});if(o&&!ALLOWED_ORIGINS.has(o))return out({error:"Origen no permitido"},403,o);if(u.pathname==="/health")return out({ok:true,service:"MiCartera news + fundamentals"},200,o);if(u.pathname==="/fundamentals"&&req.method==="GET"){const s=(u.searchParams.get("symbol")||"").trim();if(!/^[A-Za-z0-9.^=_-]{1,32}$/.test(s))return out({error:"Símbolo no válido"},400,o);try{return out(await getFundamentals(s),200,o);}catch(e){return out({error:String(e.message||e)},502,o);}}if(!env.NEWS_KV)return out({error:"Falta binding NEWS_KV"},503,o);if(u.pathname==="/symbols"&&req.method==="POST"){const b=await req.json().catch(()=>({})),list=[...new Set((b.symbols||[]).map(x=>String(x).trim().toUpperCase()).filter(x=>/^[A-Z0-9.^=_-]{1,32}$/.test(x)))].slice(0,40);await env.NEWS_KV.put("news:symbols",JSON.stringify(list));return out({ok:true,count:list.length},200,o);}if(u.pathname==="/refresh"&&req.method==="POST"){const b=await req.json().catch(()=>({})),list=(b.symbols||await symbols(env)).map(x=>String(x).toUpperCase()).filter(x=>/^[A-Z0-9.^=_-]{1,32}$/.test(x)).slice(0,40);if(!list.length)return out({error:"No hay símbolos registrados"},400,o);try{const d=await refresh(env,list);return out({ok:true,count:d.items.length,updatedAt:d.updatedAt},200,o);}catch(e){return out({error:String(e.message||e)},502,o);}}if(u.pathname==="/news"&&req.method==="GET"){const raw=await env.NEWS_KV.get("news:latest"),d=raw?JSON.parse(raw):{items:[],updatedAt:null},wanted=(u.searchParams.get("symbols")||"").split(",").map(x=>x.trim().toUpperCase()).filter(Boolean);return out({...d,items:wanted.length?d.items.filter(n=>(n.symbols||[]).some(s=>wanted.includes(s))):d.items},200,o);}return out({error:"Ruta no encontrada"},404,o);},async scheduled(event,env,ctx){ctx.waitUntil((async()=>{const list=await symbols(env);if(list.length)await refresh(env,list);})());}};
